  const oldResults=resultsView;resultsView=()=>`<div class="note">${t('Диагностика айырмасы — сипаттамалық көрсеткіш. Тапсырмалардың тең қиындығы мен өткізу жағдайы тексерілмесе, оны әдістің дәлелденген әсері деп айтуға болмайды. Өзіндік бекіту нәтижесі бөлек бағаланады.','Разница диагностик — описательный показатель. Без проверки сопоставимости заданий и условий её нельзя считать доказанным эффектом метода. Результат самостоятельного переноса оценивается отдельно.')}</div>`+oldResults();
